using UnityEngine;using UnityEditor;using System.IO;
[InitializeOnLoad]public static class KeyPickupPlayCheck{
 static int phase;static double started;static StealthGame.PlayerMovement player;static string id;static StealthGame.Key key;
 static KeyPickupPlayCheck(){if(File.Exists("Temp/key_pickup_play.request"))EditorApplication.update+=Step;}
 static void End(string text){File.WriteAllText("Temp/key_pickup_play_result.txt",text);File.Delete("Temp/key_pickup_play.request");EditorApplication.update-=Step;EditorApplication.isPlaying=false;}
 static void Step(){if(!File.Exists("Temp/key_pickup_play.request")){EditorApplication.update-=Step;return;}if(!EditorApplication.isPlaying){if(!EditorApplication.isPlayingOrWillChangePlaymode)EditorApplication.isPlaying=true;return;}if(EditorApplication.isCompiling)return;try{if(phase==0){var p=GameObject.Find("Player");if(p==null)return;player=p.GetComponent<StealthGame.PlayerMovement>();player.enabled=false;p.GetComponent<StealthGame.FirstPersonController>().enabled=false;foreach(var o in Object.FindObjectsByType<StealthGame.Observer>(FindObjectsSortMode.None))o.enabled=false;key=GameObject.Find("Key_Blue").GetComponent<StealthGame.Key>();id=key.KeyName;var bounds=key.GetComponentInChildren<Renderer>().bounds;var rb=p.GetComponent<Rigidbody>();rb.useGravity=false;rb.constraints=RigidbodyConstraints.FreezeAll;rb.position=new Vector3(bounds.center.x+.25f,0,bounds.center.z);Physics.SyncTransforms();started=EditorApplication.timeSinceStartup;phase=1;}else if(EditorApplication.timeSinceStartup-started>1){bool owned=player.OwnKey(id);End("physical_trigger_grants_key="+owned+" collected_object_removed="+(key==null));}}catch(System.Exception e){End("FAIL="+e);}}
}
